mapper.update:
UPDATE cdm_own.sup_memo /* 메모관리 */
SET
    memo_ttl_nm = #{memoTtlNm},    /* 메모 제목 명 */
    memo_cn = #{memoCn},           /* 메모 내용 */
    memo_alrm_yn = #{memoAlrmYn},  /* 메모 알람 여부 */
    memo_alrm_dt = #{memoAlrmDt},  /* 메모 알람 일시 */
    sort_sn = #{sortSn},            /* 정렬일련번호 */
    mdfcn_dt = CURRENT_TIMESTAMP,
    mdfr_id = #{userId}
WHERE 1=1
    AND user_id = #{userId}
    AND memo_ctgy_sid = #{memoCtgySid}
    AND memo_sid = #{memoSid}

mapper.delete:
