WHERE 1=1
    AND user_id = #{userId}
    AND memo_ctgy_sid = #{memoCtgySid}
    AND memo_sid = #{memoSid}

DELETE FROM cdm_own.sup_memo_ctgy /* 메모 카테고리 */
WHERE 1=1
    AND user_id = #{userId}
    AND memo_ctgy_sid = #{memoCtgySid}
